def replace_vowels_next(s):
    vowel_map = {'a': 'e', 'e': 'i', 'i': 'o', 'o': 'u', 'u': 'a'}
    result = []
    for c in s:
        if c in vowel_map:
            result.append(vowel_map[c])
        else:
            result.append(c)
    return ''.join(result)

def rotate_left(s, n):
    n = n % len(s)
    return s[n:] + s[:n]

def shift_alphabet(s, shift):
    result = []
    for c in s:
        if c.isalpha():
            if c.islower():
                shifted = chr((ord(c) - ord('a') + shift) % 26 + ord('a'))
            else:
                shifted = chr((ord(c) - ord('A') + shift) % 26 + ord('A'))
            result.append(shifted)
        else:
            result.append(c)
    return ''.join(result)

# Start with the string
s = 'ivvmpxxhmqnnlhmns'

# Step 1: Replace vowels with next vowel
s = replace_vowels_next(s)

# Step 2: Replace vowels with next vowel again
s = replace_vowels_next(s)

# Step 3: Rotate left by 6 positions
s = rotate_left(s, 6)

# Step 4: Shift by 2
s = shift_alphabet(s, 2)

# Step 5: Shift by 9
s = shift_alphabet(s, 9)

# Step 6: Shift by 8
s = shift_alphabet(s, 8)

print(f"ANSWER: {s}")
